SINA_SMART["anat1-shoulder"] = {"lecture":"anat1-shoulder","title":"The shoulder: pectoral region and axilla","mapStatus":"auto: generated by universal.py from the lecture summary and key points; not human-reviewed","los":[{"id":"anat1-shoulder:e0","text":"Shoulder: anterior (pectoral + deltoid) and posterior regions.","topic":"The big picture","sec":0,"importance":"core","highYield":"insufficient-source"},{"id":"anat1-shoulder:e1","text":"Deltopectoral groove; coracoid at its top.","topic":"The big picture","sec":0,"importance":"core","highYield":"insufficient-source"},{"id":"anat1-shoulder:e2","text":"Axilla: quadrangular pyramid, hilum of the upper limb.","topic":"Walls of the axilla","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"anat1-shoulder:e3","text":"Anterior wall: pectoralis major; pectoralis minor, subclavius, clavipectoral fascia.","topic":"Walls of the axilla","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"anat1-shoulder:e4","text":"Posterior: subscapularis, teres major. Medial: serratus anterior (long thoracic n.). Lateral: coracobrachialis, short head of biceps.","topic":"Walls of the axilla","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"anat1-shoulder:e5","text":"Cephalic vein and thoracoacromial artery pierce the clavipectoral fascia.","topic":"Contents","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"anat1-shoulder:e6","text":"Axillary artery → brachial at lower border of pectoralis major; 5 branches.","topic":"Contents","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"anat1-shoulder:e7","text":"Lateral cord: musculocutaneous, median (lateral root). Medial cord: median (medial root), ulnar. Posterior cord: axillary, radial.","topic":"Contents","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"anat1-shoulder:e8","text":"Axillary nodes drain the breast.","topic":"Contents","sec":2,"importance":"core","highYield":"insufficient-source"}],"vmap":{},"mlevel":{"1biue7o":"a","agp3nc":"a","15fl9k3":"a","qwtwir":"a","lsofv4":"a","1r9xa0t":"a","7k4s42":"a","l7y8gf":"a","nt73r":"a","18oo5w9":"a","1tmezc2":"a","1b7xl9u":"a","lkgfex":"a","afsyvo":"a"},"mapCounts":{"verified":0,"auto":14,"ambiguous":0,"missing":0},"mrules":[],"items":[],"experimental":[],"status":{},"difficulty":{},"expl":{"anat1-shoulder:e0":{"s":0,"u":["Shoulder: anterior (pectoral + deltoid) and posterior regions.","It has an anterior region (medial pectoral region with the breast, lateral deltoid region ) and a posterior (scapular) region.","Surface anatomy: the deltopectoral groove between pectoral region and deltoid, with the coracoid process palpable at its top."],"dp":[]},"anat1-shoulder:e1":{"s":0,"u":["Deltopectoral groove; coracoid at its top.","Surface anatomy: the deltopectoral groove between pectoral region and deltoid, with the coracoid process palpable at its top."],"dp":[]},"anat1-shoulder:e2":{"s":1,"u":["Axilla: quadrangular pyramid, hilum of the upper limb.","The axillary fossa is a quadrangular pyramid , the hilum of the upper limb for its vessels, nerves and lymphatics."],"dp":[]},"anat1-shoulder:e3":{"s":1,"u":["Anterior wall: pectoralis major; pectoralis minor, subclavius, clavipectoral fascia.","Anterior wall : superficial pectoralis major (from medial clavicle, sternum and first six costal cartilages, rectus sheath → lateral lip of the bicipital groove; adduction and medial rotation; pectoral nerves); deep subclavius (clavicle → 1st rib; lowers clavicle, protects subclavian vessels) and pectoralis minor (ribs 3-5 → coracoid; lowers scapula, raises ribs), wrapped in the clavipectoral fascia , which forms the suspensory ligament of the axilla and is pierced by the cephalic vein and the thoracoacromial artery ."],"dp":[]},"anat1-shoulder:e4":{"s":1,"u":["Posterior: subscapularis, teres major. Medial: serratus anterior (long thoracic n.). Lateral: coracobrachialis, short head of biceps.","Lateral wall : coracobrachialis (flexes the arm; pierced by the musculocutaneous nerve , the nerve of elbow flexion) and the short head of biceps.","Posterior wall : subscapularis (medial rotation; subscapular nerve) and the tendon of teres major ."],"dp":[{"h":"Note","t":"Axilla walls : anterior = pectoralis major and minor, subclavius, clavipectoral fascia; posterior = subscapularis, teres major, latissimus; medial = serratus anterior ; lateral = coracobrachialis and short head of biceps (bicipital groove)."},{"h":"Clinical","t":"Long thoracic nerve (serratus anterior) injury, e.g. in axillary node clearance → winged scapula when pushing against a wall."}]},"anat1-shoulder:e5":{"s":2,"u":["Cephalic vein and thoracoacromial artery pierce the clavipectoral fascia.","The axillary vein lies medial to the artery, receives the matching veins and the cephalic vein, and continues as the subclavian vein.","Axillary artery : continues the subclavian and becomes the brachial artery at the lower border of pectoralis major; five branches: thoracoacromial , superior thoracic, subscapular , inferior (lateral) thoracic, and the trunk of the anterior and posterior circumflex humeral arteries."],"dp":[{"h":"Note","t":"Clavipectoral fascia is pierced by the cephalic vein (joining the axillary vein) and the thoracoacromial artery. The musculocutaneous nerve pierces coracobrachialis ."}]},"anat1-shoulder:e6":{"s":2,"u":["Axillary artery → brachial at lower border of pectoralis major; 5 branches.","Axillary artery : continues the subclavian and becomes the brachial artery at the lower border of pectoralis major; five branches: thoracoacromial , superior thoracic, subscapular , inferior (lateral) thoracic, and the trunk of the anterior and posterior circumflex humeral arteries."],"dp":[{"h":"Note","t":"Axillary artery runs from the outer border of rib 1 to the lower border of teres major (the lecture uses pectoralis major, at about the same level), where it becomes the brachial artery. Pectoralis minor divides it into 3 parts."}]},"anat1-shoulder:e7":{"s":2,"u":["Lateral cord: musculocutaneous, median (lateral root). Medial cord: median (medial root), ulnar. Posterior cord: axillary, radial.","Brachial plexus cords around the artery: lateral cord → musculocutaneous nerve and lateral root of the median nerve; medial cord → medial root of the median, ulnar nerve, medial cutaneous nerves of arm and forearm; posterior cord → axillary (circumflex) nerve and radial nerve ."],"dp":[{"h":"Note","t":"Cords and their nerves : lateral → musculocutaneous + lateral root of median; medial → medial root of median + ulnar ; posterior → axillary + radial ."}]},"anat1-shoulder:e8":{"s":2,"u":["Axillary nodes drain the breast.","Axillary lymph nodes drain the breast , the anterolateral chest wall and the upper limb: key in breast cancer staging."],"dp":[{"h":"Why breast cancer spreads to the armpit","t":"Most lymph from the breast drains laterally to the axillary nodes arranged around the axillary vessels. Cancer cells travelling in that lymph are trapped there first, which is why surgeons sample axillary nodes (sentinel node biopsy) to stage breast cancer, and why removing them can cause arm lymphoedema. Source: the lecture's axillary lymph node section."},{"h":"Clinical","t":"Axillary nodes drain most of the breast (~75%): the key staging site in breast cancer ; clearance risks lymphoedema of the arm."}]}},"meta":{"1biue7o":{"a":"recall","vg":"anat1-shoulder:e0/recall/1"},"agp3nc":{"a":"recall","vg":"anat1-shoulder:e1/recall/1"},"15fl9k3":{"a":"recall","vg":"anat1-shoulder:e2/recall/1"},"qwtwir":{"a":"recall","vg":"anat1-shoulder:e3/recall/1"},"lsofv4":{"a":"recall","vg":"anat1-shoulder:e3/recall/2"},"1r9xa0t":{"a":"recall","vg":"anat1-shoulder:e5/recall/1"},"7k4s42":{"a":"recall","vg":"anat1-shoulder:e4/recall/1"},"l7y8gf":{"a":"recall","vg":"anat1-shoulder:e4/recall/2"},"nt73r":{"a":"recall","vg":"anat1-shoulder:e4/recall/3"},"18oo5w9":{"a":"recall","vg":"anat1-shoulder:e6/recall/1"},"1tmezc2":{"a":"recall","vg":"anat1-shoulder:e5/recall/2"},"1b7xl9u":{"a":"recall","vg":"anat1-shoulder:e7/recall/1"},"lkgfex":{"a":"recall","vg":"anat1-shoulder:e7/recall/2"},"afsyvo":{"a":"recall","vg":"anat1-shoulder:e8/recall/1"}},"explRev":"4716b4f89688"};
